const assert=require('node:assert/strict');
const crypto=require('node:crypto');
const {extract,buildBundle,bindClaims,citableFacts}=require('../src/reasoning/sourceBundle');
const source=(path,text)=>({path,version:crypto.createHash('sha256').update(text).digest('hex'),complete:true,text:text.split('\n').map((l,i)=>`${i+1}: ${l}`).join('\n')});
async function main(){
    const root=source('src/a/main.js',"const {helper}=require('../helper');\nfunction f(x){ if(!x) return null; function inner(){return 7;} return helper(x); }");
    const dep=source('src/helper.js','exports.helper = x => x;');
    const reads=[];
    const read=async p=>{reads.push(p);if(p===root.path)return root;if(p===dep.path)return dep;throw new Error('Not found');};
    const built=await buildBundle(root,{read,agentId:'alice'});
    assert.equal(built.bundle.files.length,2);assert.equal(built.bundle.dependencies[0].target,dep.path);
    const facts=built.bundle.facts;
    const inner=built.bundle.symbols.find(s=>s.name==='inner');
    assert.equal(facts.find(f=>f.kind==='return'&&f.expression==='7').owner,inner.id);
    const guardReturn=facts.find(f=>f.kind==='return'&&f.expression==='null');
    assert.equal(facts.find(f=>f.id===guardReturn.parentId).kind,'then');
    assert.equal(bindClaims({claims:[{text:'A guarded return.',evidenceIds:[guardReturn.id]}]},built.bundle)[0].citations[0].path,root.path);
    assert.throws(()=>bindClaims({claims:[{text:'fake',evidenceIds:['missing']}]},built.bundle),/reference/);
    const invalidRelations={facts:[{id:'a',relatedIds:['b']},{id:'b',relatedIds:['a']},{id:'c',relatedIds:['missing']},{id:'d',clipped:true},{id:'e',relatedIds:['d']}]};
    assert.deepEqual(citableFacts(invalidRelations),[]);
    const shadow=extract(source('src/a.js',"function f(require){return require('./secret');}"),'x');
    assert.equal(shadow.imports.length,0);
    assert.equal(extract(source('src/a.js',"const {require}=other; require('./secret');"),'x').imports.length,0);
    const cycle=await buildBundle(source('src/a.js',"require('./a'); require('fs'); require(name);"),{read});
    assert.equal(cycle.bundle.files.length,1);
    assert.equal(cycle.bundle.dependencies[0].status,'source_included');
    assert.match(cycle.bundle.dependencies[1].reason,/External/);
    assert(cycle.bundle.coverage.gaps.some(g=>/Dynamic/.test(g.reason)));
    await assert.rejects(buildBundle(root,{read,maxChars:10}),/budget/);
    const clipped=extract(source('src/long.js','function f(){ return "'+ 'a'.repeat(350)+'"; }'),'z');
    assert.throws(()=>bindClaims({claims:[{text:'long',evidenceIds:[clipped.facts.find(f=>f.kind==='return').id]}]},clipped),/clipped/);
    assert.throws(()=>extract({...root,complete:false},'x'),/complete/);
    assert.throws(()=>extract(source('src/bad.js','function {'),'x'),/parse/);
    const escape=await buildBundle(source('src/a.js',"require('../../outside');"),{read});
    assert.match(escape.bundle.dependencies[0].reason,/boundary/);
    await built.assertCurrent();
    const changing=await buildBundle(root,{read:async p=>p===root.path?root:dep});
    dep.version='changed';await assert.rejects(changing.assertCurrent(),/changed/);
    const {createService}=require('../src/reasoning/projectQuestion');
    dep.version=crypto.createHash('sha256').update('exports.helper = x => x;').digest('hex');
    const service=createService({repository:{get:async()=>null},read,evidenceBundle:true});
    const result=await service.answer({filename:root.path,question:'What does this return?'},{agentId:'alice',complete:async (messages,options)=>{
        assert.match(messages[0].content,/evidenceIds/);
        assert(options.format.properties.claims.items.properties.evidenceIds.items.enum.includes(guardReturn.id));
        return JSON.stringify({claims:[{text:'It has a guarded null return.',evidenceIds:[guardReturn.id]}],unknowns:[]});
    }});
    assert.match(result.reply,/src\/a\/main.js:2/);assert.doesNotMatch(result.speech,/src\//);
    assert.deepEqual(result.coverage.inspectedFiles,[root.path,dep.path]);
    assert.match(result.reply,/Atlas evidence coverage/);
    assert.doesNotMatch(result.speech,/extraction limits|Atlas evidence coverage/);
    console.log('Source bundle ownership, guards, dependency boundaries, freshness and ID binding passed.');
}
main().catch(e=>{console.error(e);process.exitCode=1;});
